insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$ouro-branco$q$, $q$https://www.app.ourobranco.cam.mg.gov.br/docs/legislacao/L_1973_0_2013.pdf (Lei 1.973/2013) ; https://www.app.ourobranco.cam.mg.gov.br/docs/legislacao/LEI_2897_2025.pdf (Lei 2.897/2025)$q$, $q$Atos oficiais de Ouro Branco: domínio público (Lei 9.610/1998, art. 8º, IV). Limite municipal: IBGE (dados públicos, citar a fonte), só como registro.$q$, 1, $q$Lei 1.973/2013, art. 1º: proibido o trânsito de carretas e caminhões com três eixos ou mais no Centro Histórico (exceção de carga e descarga do comércio 8h-15h e 20h-5h, que a Lei 2.897/2025 afasta no 'perímetro de tombamento histórico'). Nem o 'Centro Histórico' nem o perímetro de tombamento são delimitados nas leis; sem mapa ou ato de delimitação não há geometria honesta (o município todo é urbano em quase toda a malha, e os setores do IBGE não identificam o centro histórico). Regra registrada desativada; pendência: obter o perímetro de tombamento com a Prefeitura/IEPHA.$q$);
